<?php defined('BASEPATH') OR exit('No direct script access allowed');class Talk_model extends CI_Model{function __construct(){parent::__construct();$this->load->database();}private function access($id,$uid,$org){return $this->db->from('talk_channels c')->join('talk_members m','m.channel_id=c.id')->where(array('c.id'=>$id,'c.organization_id'=>$org,'c.is_archived'=>0,'m.user_id'=>$uid))->count_all_results()>0;}function channels($uid,$org,$q,$type,$p,$pp){$this->db->from('talk_channels c')->join('talk_members m','m.channel_id=c.id')->where(array('c.organization_id'=>$org,'c.is_archived'=>0,'m.user_id'=>$uid));if($q)$this->db->like('c.name',$q);if($type)$this->db->where('c.type',$type);$n=$this->db->count_all_results();$this->db->select('c.*')->from('talk_channels c')->join('talk_members m','m.channel_id=c.id')->where(array('c.organization_id'=>$org,'c.is_archived'=>0,'m.user_id'=>$uid));if($q)$this->db->like('c.name',$q);if($type)$this->db->where('c.type',$type);$r=$this->db->order_by('c.last_message_at','DESC')->limit($pp,($p-1)*$pp)->get()->result_array();return array('items'=>array_map(array($this,'channel_view'),$r),'pagination'=>array('page'=>$p,'perPage'=>$pp,'total'=>$n,'totalPages'=>(int)ceil($n/$pp)));}function create_channel($uid,$org,$d){$now=date('Y-m-d H:i:s');$id=$this->uuid();$r=array('id'=>$id,'organization_id'=>$org,'workspace_id'=>$d['workspaceId']??NULL,'type'=>$d['type']??'CHANNEL','access_mode'=>$d['access']??'PUBLIC','name'=>$d['name'],'topic'=>$d['topic']??NULL,'dm_peer_id'=>$d['dmPeerId']??NULL,'created_by_id'=>$uid,'is_archived'=>0,'last_message_at'=>$now,'metadata'=>'{}','created_at'=>$now,'updated_at'=>$now);$this->db->insert('talk_channels',$r);$this->add_members($id,$uid,$org,array($uid),$d['agentIds']??array());return $this->get_channel($id,$uid,$org);}function get_channel($id,$uid,$org){if(!$this->access($id,$uid,$org))return NULL;$r=$this->db->where('id',$id)->get('talk_channels')->row_array();$v=$this->channel_view($r);$v['members']=$this->members($id);return $v;}function update_channel($id,$uid,$org,$d){if(!$this->access($id,$uid,$org))return NULL;$map=array('name'=>'name','topic'=>'topic','access'=>'access_mode');$set=array('updated_at'=>date('Y-m-d H:i:s'));foreach($map as $i=>$o)if(isset($d[$i]))$set[$o]=$d[$i];$this->db->where('id',$id)->update('talk_channels',$set);return $this->get_channel($id,$uid,$org);}function archive($id,$uid,$org){if(!$this->access($id,$uid,$org))return FALSE;$this->db->where('id',$id)->update('talk_channels',array('is_archived'=>1));return TRUE;}function add_members($id,$uid,$org,$users,$agents){if(!$this->access($id,$uid,$org)&&!$this->db->where(array('id'=>$id,'created_by_id'=>$uid,'organization_id'=>$org))->count_all_results('talk_channels'))return FALSE;foreach($users as $x)if($this->db->where(array('user_id'=>$x,'organization_id'=>$org))->count_all_results('memberships')&&!$this->db->where(array('channel_id'=>$id,'user_id'=>$x))->count_all_results('talk_members'))$this->db->insert('talk_members',array('id'=>$this->uuid(),'channel_id'=>$id,'user_id'=>$x,'joined_at'=>date('Y-m-d H:i:s')));foreach($agents as $x)if($this->db->where(array('id'=>$x,'organization_id'=>$org))->count_all_results('agents')&&!$this->db->where(array('channel_id'=>$id,'agent_id'=>$x))->count_all_results('talk_members'))$this->db->insert('talk_members',array('id'=>$this->uuid(),'channel_id'=>$id,'agent_id'=>$x,'joined_at'=>date('Y-m-d H:i:s')));return TRUE;}function remove_member($id,$mid,$uid,$org){if(!$this->access($id,$uid,$org))return FALSE;$this->db->where(array('id'=>$mid,'channel_id'=>$id))->delete('talk_members');return $this->db->affected_rows()>0;}function messages($id,$uid,$org,$p,$pp,$parent){if(!$this->access($id,$uid,$org))return NULL;$this->db->where('channel_id',$id);$parent?$this->db->where('thread_parent_id',$parent):$this->db->where('thread_parent_id',NULL);$n=$this->db->count_all_results('talk_messages');$this->db->where('channel_id',$id);$parent?$this->db->where('thread_parent_id',$parent):$this->db->where('thread_parent_id',NULL);$r=$this->db->where('deleted_at',NULL)->order_by('created_at')->limit($pp,($p-1)*$pp)->get('talk_messages')->result_array();return array('items'=>array_map(array($this,'message_view'),$r),'pagination'=>array('page'=>$p,'perPage'=>$pp,'total'=>$n,'totalPages'=>(int)ceil($n/$pp)));}function send($id,$uid,$org,$d){if(!$this->access($id,$uid,$org))return NULL;$now=date('Y-m-d H:i:s');$r=array('id'=>$this->uuid(),'channel_id'=>$id,'type'=>'TEXT','content'=>$d['content'],'user_id'=>$uid,'thread_parent_id'=>$d['threadParentId']??NULL,'reply_count'=>0,'reactions'=>'{}','metadata'=>'{}','created_at'=>$now,'updated_at'=>$now);$this->db->insert('talk_messages',$r);if($r['thread_parent_id'])$this->db->where('id',$r['thread_parent_id'])->set('reply_count','reply_count+1',FALSE)->set('last_reply_at',$now)->update('talk_messages');$this->db->where('id',$id)->update('talk_channels',array('last_message_at'=>$now,'updated_at'=>$now));return $this->message_view($r);}function message($mid,$uid,$org){$r=$this->db->select('m.*')->from('talk_messages m')->join('talk_channels c','c.id=m.channel_id')->join('talk_members tm','tm.channel_id=c.id')->where(array('m.id'=>$mid,'c.organization_id'=>$org,'tm.user_id'=>$uid,'m.deleted_at'=>NULL))->get()->row_array();return $r?$this->message_view($r):NULL;}function edit_message($mid,$uid,$org,$content){$r=$this->db->select('m.*')->from('talk_messages m')->join('talk_channels c','c.id=m.channel_id')->where(array('m.id'=>$mid,'m.user_id'=>$uid,'c.organization_id'=>$org,'m.deleted_at'=>NULL))->get()->row_array();if(!$r)return NULL;$now=date('Y-m-d H:i:s');$this->db->where('id',$mid)->update('talk_messages',array('content'=>$content,'edited_at'=>$now,'updated_at'=>$now));return $this->message($mid,$uid,$org);}function delete_message($mid,$uid,$org){$r=$this->db->select('m.*')->from('talk_messages m')->join('talk_channels c','c.id=m.channel_id')->where(array('m.id'=>$mid,'m.user_id'=>$uid,'c.organization_id'=>$org))->get()->row_array();if(!$r)return FALSE;$this->db->where('id',$mid)->update('talk_messages',array('content'=>'[deleted]','deleted_at'=>date('Y-m-d H:i:s'),'updated_at'=>date('Y-m-d H:i:s')));return TRUE;}function reaction($mid,$uid,$org,$emoji){$v=$this->message($mid,$uid,$org);if(!$v)return NULL;$r=$this->db->where('id',$mid)->get('talk_messages')->row_array();$all=json_decode($r['reactions'],TRUE)?:array();$users=$all[$emoji]??array();if(in_array($uid,$users,TRUE))$users=array_values(array_diff($users,array($uid)));else$users[]=$uid;if($users)$all[$emoji]=$users;else unset($all[$emoji]);$this->db->where('id',$mid)->update('talk_messages',array('reactions'=>json_encode($all),'updated_at'=>date('Y-m-d H:i:s')));return $all;}private function members($id){return $this->db->where('channel_id',$id)->get('talk_members')->result_array();}function channel_view($r){return array('id'=>$r['id'],'type'=>strtolower($r['type']),'access'=>strtolower($r['access_mode']),'name'=>$r['name'],'topic'=>$r['topic'],'isArchived'=>(bool)$r['is_archived'],'lastMessageAt'=>$r['last_message_at'],'createdById'=>$r['created_by_id'],'createdAt'=>$r['created_at'],'updatedAt'=>$r['updated_at'],'members'=>array());}function message_view($r){return array('id'=>$r['id'],'channelId'=>$r['channel_id'],'type'=>strtolower($r['type']),'content'=>$r['content'],'userId'=>$r['user_id']??NULL,'agentId'=>$r['agent_id']??NULL,'threadParentId'=>$r['thread_parent_id'],'replyCount'=>(int)$r['reply_count'],'reactions'=>json_decode($r['reactions'],TRUE)?:array(),'editedAt'=>$r['edited_at']??NULL,'createdAt'=>$r['created_at']);}private function uuid(){$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($b),4));}}
